INSERT INTO questions (mode, class_id, public, active, data, created_at, skill, min_floor, max_floor, rules) SELECT 1, NULL, 1, 1, '{"correct":"“Did you tell Mei the bridge is closed?” asked Raj.\n“No, I never said that,” replied Tally.","prompt":"“Did you tell Mei the bridge is closed?” asked Raj. “No, I never said that,” replied Tally.","alts":[],"instruction":"Give each speaker their own line.","lines":true,"seed":"sk-core-1a"}', 1792296240907, 'speaker_lines', NULL, NULL, 256 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE json_extract(data, '$.seed') = 'sk-core-1a');
INSERT INTO questions (mode, class_id, public, active, data, created_at, skill, min_floor, max_floor, rules) SELECT 1, NULL, 1, 1, '{"correct":"Mei looked at the clock. “We’re going to be late,” groaned Mei.","prompt":"mei looked at the clock we’re going to be late groaned mei","alts":[],"beat":true,"seed":"sk-core-1b"}', 1792296240907, 'action_beat', NULL, NULL, 622 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE json_extract(data, '$.seed') = 'sk-core-1b');
INSERT INTO questions (mode, class_id, public, active, data, created_at, skill, min_floor, max_floor, rules) SELECT 4, NULL, 1, 1, '{"stem":"“Open the gate!” said the guard. Which verb is the best upgrade for “said”?","options":[{"id":"a","text":"whispered"},{"id":"b","text":"bellowed"},{"id":"c","text":"giggled"},{"id":"d","text":"wondered"}],"correct":["b"],"pick":1,"explanation":"It’s an order, and orders are shouted. Bellowed shows the volume and the guard’s attitude.","context":"The Overlord’s guard barks an order.","code":"MC_VERB","seed":"sk-core-2a"}', 1792296240907, 'verb_choice', NULL, NULL, 128 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE json_extract(data, '$.seed') = 'sk-core-2a');
INSERT INTO questions (mode, class_id, public, active, data, created_at, skill, min_floor, max_floor, rules) SELECT 5, NULL, 1, 1, '{"prompt":"“I am going to the Warren,” said Brisk.","instruction":"Rewrite as reported speech.","kind":"reported","accepted":["Brisk said (that) she was going to the Warren."],"traps":[{"words":["i","my","me"],"code":"RS_PRONOUN"},{"words":["am","is","are"],"code":"RS_TENSE"}],"seed":"sk-core-4a"}', 1792296240907, 'reported', NULL, NULL, 1024 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE json_extract(data, '$.seed') = 'sk-core-4a');
INSERT INTO questions (mode, class_id, public, active, data, created_at, skill, min_floor, max_floor, rules) SELECT 5, NULL, 1, 1, '{"prompt":"Wren told Quip that she would ring the bell the next day.","instruction":"Rewrite as direct speech.","kind":"direct","accepted":["Wren said to Quip, “I will ring the bell tomorrow.”","Wren told Quip, “I will ring the bell tomorrow.”","Wren said to Quip, “I’ll ring the bell tomorrow.”","Wren told Quip, “I’ll ring the bell tomorrow.”"],"traps":[{"words":["she","her"],"code":"DS_PRONOUN"},{"words":["would"],"code":"DS_TENSE"},{"words":["next"],"code":"DS_TIME"}],"seed":"sk-core-4b"}', 1792296240907, 'reported', NULL, NULL, 2048 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE json_extract(data, '$.seed') = 'sk-core-4b');
INSERT INTO questions (mode, class_id, public, active, data, created_at, skill, min_floor, max_floor, rules) SELECT 6, NULL, 1, 1, '{"sentence":"The knight walked into the hall and sees a crown.","wrong":["sees"],"fixes":["saw"],"seed":"sk-core-4c"}', 1792296240907, 'tense_fix', NULL, NULL, 4096 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE json_extract(data, '$.seed') = 'sk-core-4c');
INSERT INTO questions (mode, class_id, public, active, data, created_at, skill, min_floor, max_floor, rules) SELECT 4, NULL, 1, 1, '{"stem":"How does Ilse really feel?","options":[{"id":"a","text":"calm"},{"id":"b","text":"worried but hiding it"},{"id":"c","text":"bored"},{"id":"d","text":"angry with Wren"}],"correct":["b"],"pick":1,"explanation":"Her words say “fine”, but her folded arms, her long stare at the door and her refusal to turn around show she is worried and hiding it.","passage":"“I’m fine,” said Ilse, folding her arms.\nWren smiled gently. “You’ve been staring at that door for an hour.”\n“It’s just a door,” Ilse muttered, but she did not turn around.","group":"ilse-door","code":"MC_INFER","seed":"sk-core-7a"}', 1792296240907, 'reading_between', NULL, NULL, 8192 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE json_extract(data, '$.seed') = 'sk-core-7a');
INSERT INTO questions (mode, class_id, public, active, data, created_at, skill, min_floor, max_floor, rules) SELECT 4, NULL, 1, 1, '{"stem":"Which TWO details show she isn’t “fine”?","options":[{"id":"a","text":"folding her arms"},{"id":"b","text":"staring at the door for an hour"},{"id":"c","text":"muttered"},{"id":"d","text":"did not turn around"},{"id":"e","text":"Wren smiled"},{"id":"f","text":"the door is mentioned"}],"correct":["a","b","c","d"],"pick":2,"explanation":"Folded arms, a long stare, a mutter and not turning around all show tension. Wren’s smile and the door being mentioned say nothing about how Ilse feels.","passage":"“I’m fine,” said Ilse, folding her arms.\nWren smiled gently. “You’ve been staring at that door for an hour.”\n“It’s just a door,” Ilse muttered, but she did not turn around.","group":"ilse-door","code":"MC_INFER","seed":"sk-core-7b"}', 1792296240907, 'reading_between', NULL, NULL, 8192 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE json_extract(data, '$.seed') = 'sk-core-7b');
INSERT INTO questions (mode, class_id, public, active, data, created_at, skill, min_floor, max_floor, rules) SELECT 4, NULL, 1, 1, '{"stem":"Why does Wren smile gently?","options":[{"id":"a","text":"to laugh at Ilse"},{"id":"b","text":"because the door is funny"},{"id":"c","text":"to show she understands and isn’t scolding"},{"id":"d","text":"to tell Ilse to be quiet"}],"correct":["c"],"pick":1,"explanation":"A gentle smile with kind words shows Wren understands. She is noticing, not telling Ilse off.","passage":"“I’m fine,” said Ilse, folding her arms.\nWren smiled gently. “You’ve been staring at that door for an hour.”\n“It’s just a door,” Ilse muttered, but she did not turn around.","group":"ilse-door","code":"MC_INFER","seed":"sk-core-7c"}', 1792296240907, 'reading_between', NULL, NULL, 8192 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE json_extract(data, '$.seed') = 'sk-core-7c');
